/* OMR review page: original score image vs. lilylet rendering.
 *
 * Render pipeline (all in the browser, same as lilylet's score-player):
 *   lyl text --LilyletLib.parseCode + meiEncoder.encode--> MEI --Verovio WASM--> SVG
 *
 * Data comes from data.js (window.OMR_REVIEW), generated by build.mjs. Cards are
 * rendered lazily as they scroll into view, one at a time on a shared toolkit.
 */
(function () {
	"use strict";

	const DATA = window.OMR_REVIEW;
	const $ = (id) => document.getElementById(id);
	const els = {
		meta: $("meta"), renderer: $("renderer"), list: $("list"), empty: $("empty"),
		q: $("q"), status: $("status"), dir: $("dir"), hideDiagrams: $("hideDiagrams"),
		tpl: $("card-tpl"),
	};

	if (!DATA || !window.LilyletLib) {
		els.renderer.textContent = "缺少 data.js 或 lilylet bundle：请先运行 npm run omr-review";
		els.renderer.classList.add("err");
		return;
	}

	// Paths in data.js are repo-relative; this page lives in omr-review/.
	const toUrl = (p) => "../" + p.split("/").map(encodeURIComponent).join("/");

	const VEROVIO_OPTIONS = { scale: 40, adjustPageHeight: true, adjustPageWidth: true, breaks: "auto", pageWidth: 2100, pageHeight: 2970 };

	// --- Verovio init (shared toolkit) ---
	let toolkit = null;
	const toolkitReady = new Promise((resolve, reject) => {
		const start = () => {
			const v = window.verovio;
			if (!v) return reject(new Error("verovio script not loaded"));
			const make = () => {
				try {
					toolkit = new v.toolkit();
					// keep warnings in the toolkit buffer so getLog() returns them per render
					if (v.enableLogToBuffer) v.enableLogToBuffer(true);
					if (v.enableLog && v.LOG_WARNING !== undefined) v.enableLog(v.LOG_WARNING);
					resolve(toolkit);
				} catch (e) { reject(e); }
			};
			if (v.module.calledRun) make();
			else v.module.onRuntimeInitialized = make;
		};
		if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", start);
		else start();
	});

	toolkitReady.then((tk) => {
		els.renderer.textContent = `Verovio ${tk.getVersion ? tk.getVersion() : DATA.verovio} 已就绪 · lilylet ${DATA.lilylet}`;
		pump();
	}, (e) => {
		els.renderer.textContent = "Verovio 加载失败：" + (e && e.message ? e.message : e);
		els.renderer.classList.add("err");
	});

	// --- render one lyl source ---
	const renderLyl = (code) => {
		const L = window.LilyletLib;
		const doc = L.parseCode(code);
		const parseWarnings = (L.getParseWarnings ? L.getParseWarnings() : []).map((w) => w.message);
		const mei = L.meiEncoder.encode(doc);
		toolkit.setOptions(VEROVIO_OPTIONS);
		if (!toolkit.loadData(mei)) throw new Error("Verovio 无法载入 MEI\n" + (toolkit.getLog() || ""));
		const vrvLog = (toolkit.getLog() || "").split("\n").map((s) => s.trim()).filter(Boolean);
		const pages = [];
		for (let p = 1, n = toolkit.getPageCount(); p <= n; p++) pages.push(toolkit.renderToSVG(p));
		// collapse repeated Verovio warnings ("Slur ... not encoded ..." etc.) into counts
		const counts = new Map();
		for (const line of vrvLog) {
			const key = line.replace(/'[^']*'/g, "'…'");
			counts.set(key, (counts.get(key) || 0) + 1);
		}
		const vrvWarnings = [...counts].map(([k, n]) => (n > 1 ? `${k} ×${n}` : k));
		return { pages, measures: doc.measures.length, warnings: parseWarnings.concat(vrvWarnings), parseWarnings };
	};

	// Split a markdown source into text and ```lyl / ```lilylet code blocks.
	const splitMarkdown = (md) => {
		const segs = [];
		const re = /^```[ \t]*(lyl|lilylet)[^\n]*\n([\s\S]*?)^```[ \t]*$/gm;
		let last = 0, m;
		while ((m = re.exec(md))) {
			if (m.index > last) segs.push({ type: "text", text: md.slice(last, m.index) });
			segs.push({ type: "lyl", code: m[2] });
			last = re.lastIndex;
		}
		if (last < md.length) segs.push({ type: "text", text: md.slice(last) });
		return segs;
	};

	// --- lazy render queue ---
	const queue = [];
	let busy = false;
	const pump = () => {
		if (busy || !toolkit || !queue.length) return;
		busy = true;
		const card = queue.shift();
		setTimeout(() => {
			try { fillRender(card); } finally { busy = false; pump(); }
		}, 0);
	};

	const fillRender = (card) => {
		const item = card._item;
		const box = card.querySelector(".render");
		const warnList = card.querySelector(".warnings");
		const tags = card.querySelector(".tags");
		box.textContent = "";
		const addWarnings = (list, prefix) => {
			for (const w of list) {
				const li = document.createElement("li");
				li.textContent = prefix + w;
				warnList.appendChild(li);
			}
		};
		try {
			if (item.format === "md") {
				// markdown source: text segments as plain paragraphs, each ```lyl block as its own score
				const segs = splitMarkdown(item.code);
				let scores = 0, measures = 0, nParse = 0, nWarn = 0, failed = 0;
				for (const seg of segs) {
					if (seg.type === "text") {
						for (const line of seg.text.split(/\n{2,}/)) {
							const t = line.trim();
							if (!t) continue;
							const h = /^(#{1,6})\s+(.*)$/.exec(t);
							const el = document.createElement(h ? "h3" : "p");
							el.className = h ? "md-h" : "md-p";
							el.textContent = h ? h[2] : t;
							box.appendChild(el);
						}
						continue;
					}
					scores++;
					const wrap = document.createElement("div");
					wrap.className = "md-score";
					box.appendChild(wrap);
					try {
						const res = renderLyl(seg.code);
						wrap.innerHTML = res.pages.join("");
						measures += res.measures;
						nParse += res.parseWarnings.length;
						nWarn += res.warnings.length;
						addWarnings(res.warnings, `#${scores}: `);
					} catch (e) {
						failed++;
						const p = document.createElement("p");
						p.className = "placeholder err";
						p.textContent = `#${scores} 渲染失败：` + (e && e.message ? e.message : e);
						wrap.appendChild(p);
					}
				}
				card.querySelector(".pane-render .cap-text").textContent =
					`lilylet 渲染（markdown）· ${scores} 段 · ${measures} 小节`;
				if (failed) tags.appendChild(tag(`${failed} 段渲染失败`, "err"));
				if (nParse) tags.appendChild(tag(`${nParse} 条解析警告`, "warn"));
				else if (nWarn) tags.appendChild(tag(`${nWarn} 条渲染警告`, "warn"));
				return;
			}
			const res = renderLyl(item.code);
			box.innerHTML = res.pages.join("");
			card.querySelector(".pane-render .cap-text").textContent =
				`lilylet 渲染 · ${res.measures} 小节${res.pages.length > 1 ? ` · ${res.pages.length} 页` : ""}`;
			addWarnings(res.warnings, "");
			if (res.parseWarnings.length) tags.appendChild(tag(`${res.parseWarnings.length} 条解析警告`, "warn"));
			else if (res.warnings.length) tags.appendChild(tag(`${res.warnings.length} 条渲染警告`, "warn"));
		} catch (e) {
			const p = document.createElement("p");
			p.className = "placeholder err";
			p.textContent = "渲染失败：" + (e && e.message ? e.message : e);
			box.appendChild(p);
			tags.appendChild(tag("渲染失败", "err"));
		}
	};

	const io = new IntersectionObserver((entries) => {
		for (const ent of entries) {
			if (!ent.isIntersecting) continue;
			io.unobserve(ent.target);
			queue.push(ent.target);
		}
		pump();
	}, { rootMargin: "600px 0px" });

	// --- cards ---
	const tag = (text, cls) => {
		const s = document.createElement("span");
		s.className = "tag tag-" + cls;
		s.textContent = text;
		return s;
	};

	const SOURCE_LABEL = { omr: "OMR", hand: "手工" };

	// --- copy local path ---
	const localPath = (p) => (DATA.root ? DATA.root.replace(/\/$/, "") + "/" : "") + p;

	const copyText = async (text) => {
		// Clipboard API needs a secure context (localhost / file:// in Chrome); fall back to execCommand.
		if (navigator.clipboard && window.isSecureContext) {
			try { await navigator.clipboard.writeText(text); return true; } catch (e) { /* fall through */ }
		}
		const ta = document.createElement("textarea");
		ta.value = text;
		ta.setAttribute("readonly", "");
		ta.style.position = "fixed";
		ta.style.opacity = "0";
		document.body.appendChild(ta);
		ta.select();
		let ok = false;
		try { ok = document.execCommand("copy"); } catch (e) { ok = false; }
		ta.remove();
		return ok;
	};

	document.addEventListener("click", async (ev) => {
		const link = ev.target.closest(".copy-path");
		if (!link || ev.button !== 0 || ev.metaKey || ev.ctrlKey || ev.shiftKey || ev.altKey) return;
		ev.preventDefault();
		const status = link.parentNode.querySelector(".copy-status");
		const ok = await copyText(link.dataset.path);
		status.textContent = ok ? "已复制" : "复制失败：" + link.dataset.path;
		status.classList.toggle("err", !ok);
		clearTimeout(status._t);
		if (ok) status._t = setTimeout(() => { status.textContent = ""; }, 1500);
	});

	const cards = DATA.items.map((item) => {
		const card = els.tpl.content.firstElementChild.cloneNode(true);
		card._item = item;
		card.id = "img-" + item.image.replace(/[^A-Za-z0-9_-]+/g, "-");
		const nameEl = card.querySelector(".card-name");
		if (item.source === "omr") {
			// star marks OMR-generated lilylet; the "OMR" tag carries the same info for screen readers
			const star = document.createElement("span");
			star.className = "omr-star";
			star.setAttribute("aria-hidden", "true");
			star.title = "OMR 生成";
			star.textContent = "★";
			nameEl.appendChild(star);
		}
		nameEl.appendChild(document.createTextNode(item.name));
		card.querySelector(".path").textContent = item.dir;

		const tags = card.querySelector(".tags");
		if (item.lyl) tags.appendChild(tag(SOURCE_LABEL[item.source] || item.source, item.source));
		else tags.appendChild(tag("尚无 lilylet", "none"));
		if (item.kind === "diagram") tags.appendChild(tag("SVG 示意图", "diagram"));

		const img = card.querySelector("img");
		img.src = toUrl(item.image);
		img.alt = "原图：" + item.image;

		if (item.lyl) {
			const link = card.querySelector(".copy-path");
			link.hidden = false;
			link.href = toUrl(item.lyl);  // middle-click / open-in-new-tab still shows the file
			link.textContent = item.lyl;
			link.title = "点击复制本地路径：" + localPath(item.lyl);
			link.dataset.path = localPath(item.lyl);
		}

		const box = card.querySelector(".render");
		const p = document.createElement("p");
		p.className = "placeholder";
		p.textContent = item.lyl ? "等待渲染…" : "（尚无 lilylet 代码）";
		box.appendChild(p);

		card.querySelector(".pages").textContent =
			(item.lyl ? `lilylet：${item.lyl}\n` : "") +
			(item.pages.length ? "引用页面：" + item.pages.join("、") : "未被任何页面引用");
		card.querySelector(".pages").style.whiteSpace = "pre-line";
		if (item.code) card.querySelector(".code").textContent = item.code;
		else card.querySelector(".more").hidden = !item.pages.length;

		card._search = (item.image + " " + (item.lyl || "") + " " + item.pages.join(" ")).toLowerCase();
		els.list.appendChild(card);
		if (item.lyl) io.observe(card);
		return card;
	});

	// --- filters ---
	const dirs = [...new Set(DATA.items.map((i) => i.dir))].sort((a, b) => a.localeCompare(b));
	for (const d of dirs) {
		const o = document.createElement("option");
		o.value = d;
		o.textContent = `${d} (${DATA.items.filter((i) => i.dir === d).length})`;
		els.dir.appendChild(o);
	}

	const applyFilters = () => {
		const q = els.q.value.trim().toLowerCase();
		const st = els.status.value;
		const dir = els.dir.value;
		const hideDiagrams = els.hideDiagrams.checked;
		let shown = 0;
		for (const card of cards) {
			const it = card._item;
			let ok = true;
			if (q && !card._search.includes(q)) ok = false;
			if (dir && it.dir !== dir) ok = false;
			if (hideDiagrams && it.kind === "diagram") ok = false;
			if (st === "lyl" && !it.lyl) ok = false;
			if (st === "none" && it.lyl) ok = false;
			if ((st === "omr" || st === "hand") && it.source !== st) ok = false;
			card.hidden = !ok;
			if (ok) shown++;
		}
		els.empty.hidden = shown > 0;
		const total = DATA.items.length;
		const withLyl = DATA.items.filter((i) => i.lyl).length;
		const omr = DATA.items.filter((i) => i.source === "omr").length;
		els.meta.textContent = `显示 ${shown} / ${total} 张图片 · 已有 lilylet ${withLyl}（★ OMR ${omr}，手工 ${withLyl - omr}）· 数据生成于 ${new Date(DATA.generated).toLocaleString()}` +
			(DATA.orphans.length ? ` · ${DATA.orphans.length} 个 .lyl 未匹配到图片` : "");
		saveFilters();
	};

	// remember filters per viewer (convenience only)
	const KEY = "omr-review-filters";
	const saveFilters = () => {
		try {
			localStorage.setItem(KEY, JSON.stringify({ q: els.q.value, status: els.status.value, dir: els.dir.value, hideDiagrams: els.hideDiagrams.checked }));
		} catch (e) { /* storage unavailable */ }
	};
	try {
		const s = JSON.parse(localStorage.getItem(KEY) || "null");
		if (s) {
			els.q.value = s.q || "";
			if ([...els.status.options].some((o) => o.value === s.status)) els.status.value = s.status;
			if ([...els.dir.options].some((o) => o.value === s.dir)) els.dir.value = s.dir;
			els.hideDiagrams.checked = !!s.hideDiagrams;
		}
	} catch (e) { /* storage unavailable */ }

	els.q.addEventListener("input", applyFilters);
	for (const el of [els.status, els.dir, els.hideDiagrams]) el.addEventListener("change", applyFilters);
	applyFilters();

	if (location.hash) {
		const target = document.getElementById(location.hash.slice(1));
		if (target) target.scrollIntoView();
	}
})();
